  -- how far the slot-0 strip's top sits below a lone strip's top on sub-page 1 (title and rule move with it)
  function G.p_title_dy()
    local n = #G.PSUB[0]
    local k = G.PSUB_SCALE[n] or 1
    return (G.PSUB_Y[n][1] - 46 * k) - (G.PSUB_Y[1][1] - 46)
