  -- the form of the aura the page shows (nil = none) and its slot
  function G.hiper_target(c)
    if c == 0 or type(CharacterReforged.hyper_page_skill) ~= "function" or type(CharacterReforged.hyper_page_mix_of) ~= "function" then
      return nil
    end
    local okS, sk = pcall(CharacterReforged.hyper_page_skill, c)
    if not okS or type(sk) ~= "number" or sk == 0 then
      return nil
    end
    local okM, mix = pcall(CharacterReforged.hyper_page_mix_of, c)
    local slot = (okM and mix == sk) and "mix" or "aura"
    return G.first_form(G.SLOT_FORMS[slot]), slot
  end
  function G.hiper_double_set(view, c, why)
    if (CharacterReforged.HYPER_PAGE_MIXIMAX_VIEW == true) ~= view then
      CharacterReforged.HYPER_PAGE_MIXIMAX_VIEW = view
      if type(CharacterReforged.hyper_page_show) == "function" and c ~= 0 then
        pcall(CharacterReforged.hyper_page_show, c)
      end
    end
    G.hiperTgt, G.hiperSlot = G.hiper_target(c)
    pcall(funcLuaCommand, C.LOG, "PlayerPage hiper view", tostring(why), view and "mix" or "aura", tostring(G.hiperTgt))
  end
  function G.hiper_toggle(why)
    if not On() or G.ptype ~= G.HIPER_TYPE then
      return
    end
    if G.hiperDouble == true then
      G.mlast = G.mtick or 0
      pcall(funcLuaCommand, 1917805374, G.MX_SOUND)
      G.hiper_double_set(CharacterReforged.HYPER_PAGE_MIXIMAX_VIEW ~= true, G.hiper_chara(), why)
      return
    end
    if G.hiperTgt == nil then
      return
    end
    G.mlast = G.mtick or 0
    G.hiperOn = not G.hiperOn
    pcall(funcLuaCommand, 1917805374, G.MX_SOUND)
    pcall(funcLuaCommand, C.LOG, "PlayerPage hiper form", tostring(why), tostring(G.hiperSlot), tostring(G.hiperTgt),
      tostring(G.hiperOn))
  end
  function G.hiper_form_step()
    if not On() or not G.H.pages or G.ptype ~= G.HIPER_TYPE or G.in_office() then
      G.hiperKey, G.hiperTgt, G.hiperDouble, G.hiperBase = nil, nil, nil, nil
      return
    end
    local M = CharacterReforged.page_model
    local c = G.hiper_chara()
    local n = type(M) == "table" and type(M.forms) == "table" and #M.forms or 0
    local base = string.format("%s:%s:%d", tostring(c), tostring(type(M) == "table" and M.fhdl), n)
    local key = base .. ":" .. tostring(CharacterReforged.HYPER_PAGE_MIXIMAX_VIEW)
    if key ~= G.hiperKey then                -- entering, another player, the other slot, the forms loaded
      G.hiperKey = key
      local okc, can = false, false
      if type(CharacterReforged.hyper_page_can_switch) == "function" and c ~= 0 then
        okc, can = pcall(CharacterReforged.hyper_page_can_switch, c)
      end
      G.hiperDouble = okc and can == true
      G.hiperTgt, G.hiperSlot = G.hiper_target(c)
      G.hiperOn = G.hiperTgt ~= nil and G.cur_form() == G.hiperTgt
      pcall(funcLuaCommand, C.LOG, "PlayerPage hiper form", "slot", tostring(G.hiperSlot), tostring(G.hiperTgt),
        tostring(G.hiperOn), G.hiperDouble and "double" or "single")
      if G.hiperDouble and base ~= G.hiperBase and CharacterReforged.HYPER_PAGE_MIXIMAX_VIEW ~= true then
        local mf = G.first_form(G.SLOT_FORMS.mix)
        if mf ~= nil and mf ~= 0 and G.cur_form() == mf then   -- the model already in the mix slot's form
          G.hiper_double_set(true, c, "page")
        end
      end
      G.hiperBase = base
    end
    if G.hiperTgt == nil and G.hiperDouble ~= true then
      return
    end
    G.mtick = (G.mtick or 0) + 1
    if G.mtick - (G.mlast or -100) >= 8 then
      if G.form_key_down() then
        G.hiper_toggle("R3")
      end
    end
    if type(M) == "table" and type(M.show_form) == "function" and M.appearance == nil then
      local f
      if G.hiperDouble == true then
        f = G.hiperTgt or 0                  -- the shown slot's form, Normal without one
      else
        f = G.hiperOn and G.hiperTgt or 0
      end
      if G.cur_form() ~= f then
        pcall(M.show_form, f)
      end
    end
  end

  -- Glyphs per slot, including the mode change.
  G.SLOT_GLYPH = {[0] = {1236041562, 2355602533},
    [1] = {2097684629, 779534048},
    [2] = {1556354352, 1564866736},
    [3] = {4040371016, 131650316},
    [6] = {3019994783, 444648923}}
  function G.slot_glyph(skill, lit)
    local t = nil
    if type(CharacterReforged.hyper_card) == "table" and type(CharacterReforged.hyper_card.aura_type) == "function" and type(skill) == "number" and skill ~= 0 then
      local ok, v = pcall(CharacterReforged.hyper_card.aura_type, skill)
      t = ok and v or nil
    end
    local g = (t ~= nil and G.SLOT_GLYPH[t]) or G.SLOT_GLYPH[0]
    return g[lit and 1 or 2], t
  end
  -- Returns a double hyper's badge.
  function G.hiper_double_glyphs()
    local c = G.hiper_chara()
    if c == 0 or type(CharacterReforged.hyper_page_mix_of) ~= "function" or type(CharacterReforged.hyper_page_aura_of) ~= "function" then
      return nil
    end
    local okM, mix = pcall(CharacterReforged.hyper_page_mix_of, c)
    local okA, aura = pcall(CharacterReforged.hyper_page_aura_of, c)
    if not (okM and okA) then
      return nil
    end
    local mv = CharacterReforged.HYPER_PAGE_MIXIMAX_VIEW == true
    local gm, tm = G.slot_glyph(mix, mv)
    local ga, ta = G.slot_glyph(aura, not mv)
    return {gm, ga}, string.format("d%s:%s:%s", mv and "m" or "a", tostring(tm), tostring(ta))
  end

  -- The form badge on PERFIL shows while the player has more than one form.
  G.FBADGE = 2774128188
  G.FB_TRACE = {[0] = 3675388528, 2887174886, 891263836}
  G.FB_KEY = 2                               -- the RS key's plate instance
  G.FB_PLATE = 2563121246          -- the key's light plate
  G.FORM_GLYPHS = {[0] = {1928178275}, {1556354352}, {2097684629},
    {133970649, 1556354352}, {2097684629, 1556354352}}
  G.FB_AT = {1700, 262}                      -- the badge row's centre (screen px)
  G.FB_S, G.FB_GAP = 40, 6                   -- tile / key plate size, gap between them (screen px)
  G.FB_KEY_K = 0.8                           -- the key text's scale
  G.FB_KEY_DX, G.FB_KEY_DY = 3, -4
  G.FLABEL = 1427033801
  G.N_AREA_TEXT = 1899787537
  G.N_AREA_BASE = 3516146179
  function G.fb_hide()
    G.fbKey, G.fbBox = nil, nil
    for i = 0, 2 do
      if Exists(G.FBADGE) and Cmd(C.IS_OPEN, G.FBADGE, i) == true then
        Cmd(C.VIS, G.FBADGE, i, false)
      end
    end
    if Exists(G.FLABEL) and Cmd(C.IS_OPEN, G.FLABEL, 0) == true then
      Cmd(C.VIS, G.FLABEL, 0, false)
    end
  end
  -- Places one gauge copy as a tile.
  function G.fb_place(i, sprite, left, top, s)
    local L = G.FBADGE
    if not G.ready[L * 16 + i] then
      G.ready[L * 16 + i] = true
      Cmd(C.TRACE, G.PAGE, 0, G.FB_TRACE[i], true)
      for _, m in ipairs({G.N_TOP, G.N_SIDE, 2043683848}) do
        Cmd(C.MESH, L, m, false, i)
      end
    end
    local sx, sy = s / 476, s / 44
    Cmd(C.SPRITE, L, G.TX_OWN, sprite, G.SP_FRAME, 0, i)
    Cmd(C.SCALE, L, sx, sy, 1, i)
    Cmd(C.POS, L, left - 94 * sx, -top + 816 * sy, 0, i)
  end
  function G.form_badge()
    local glyphs, f = nil, nil
    if On() and G.ptype == CharacterReforged.PLAYER_PAGE_DESCRIPTION_TYPE and G.form_count() > 1 and not G.view_offered() and not G.in_office() then
      local M = CharacterReforged.page_model
      f = M.forms[M.fidx or 1] or 0
      glyphs = G.FORM_GLYPHS[f]
    elseif On() and G.ptype == G.HIPER_TYPE and not G.in_office() and G.hiperDouble == true then
      glyphs, f = G.hiper_double_glyphs()      -- a double hyper, both slots (the shown one lit)
    elseif On() and G.ptype == G.HIPER_TYPE and not G.in_office() and G.hiperTgt ~= nil then
      f = G.hiperOn and G.hiperTgt or 0      -- the Hiper page, Normal / the shown aura's form
      glyphs = G.FORM_GLYPHS[f]
    elseif On() and G.ptype == CharacterReforged.PLAYER_PAGE_STATS_TYPE and not G.in_office() and G.mx_avail() then
      f = CharacterReforged.stat_radar.mx == true and 1 or 0       -- ATRIBUTOS, Normal / Miximax (G.mx_step)
      glyphs = G.FORM_GLYPHS[f]
    end
    local L, T = G.FBADGE, G.FLABEL
    if glyphs == nil or not Exists(L) or not Exists(T) then
      -- an instance opened for a badge that never finished stays hidden (no raw gauge)
      G.fb_hide()
      return
    end
    local n = #glyphs
    for i = 0, n - 1 do
      if not Ready(L, i) then
        return
      end
    end
    if not Ready(L, G.FB_KEY) or not Ready(T, 0) then
      return
    end
    if not G.ready[T * 16] then
      G.ready[T * 16] = true
      G.fbKey = nil
      Cmd(C.TRACE, G.PAGE, 0, T, true)
      Cmd(C.MESH, T, G.N_AREA_BASE, false, 0)
      Cmd(C.SCALE, T, G.FB_KEY_K, G.FB_KEY_K, 1, 0)
      Cmd(C.SET_TEXT, T, G.N_AREA_TEXT, G.form_glyph(), 0)
      Cmd(2735666188 --[[text visible]], T, G.N_AREA_TEXT, true, 0)
    end
    for i = 0, n - 1 do
      if not G.ready[L * 16 + i] then
        G.fbKey = nil                          -- an instance (re)opened: place it again
      end
    end
    if not G.ready[L * 16 + G.FB_KEY] then
      G.fbKey = nil
    end
    local key = tostring(f) .. "/" .. n
    if G.fbKey ~= key then
      G.fbKey = key
      local s, gap = G.FB_S, G.FB_GAP
      local w = (n + 1) * s + n * gap
      local left, top = G.FB_AT[1] - w / 2, G.FB_AT[2] - s / 2
      for i = 0, n - 1 do
        G.fb_place(i, glyphs[i + 1], left + i * (s + gap), top, s)
      end
      for i = n, G.FB_KEY - 1 do               -- a tile the form does not use
        if Cmd(C.IS_OPEN, L, i) == true then
          Cmd(C.VIS, L, i, false)
        end
      end
      local kx = left + n * (s + gap)
      G.fb_place(G.FB_KEY, G.FB_PLATE, kx, top, s)
      Cmd(C.POS, T, kx + G.FB_KEY_DX + 165 * G.FB_KEY_K, -(G.FB_AT[2] + G.FB_KEY_DY), 0, 0)
      G.fbBox = {left, top, w, s}              -- the pointer zone (click = next form)
      pcall(funcLuaCommand, C.LOG, "PlayerPage form badge", tostring(f), n, string.format("%.0f", left))
    end
    for i = 0, n - 1 do
      Cmd(C.VIS, L, i, true)
    end
    Cmd(C.VIS, L, G.FB_KEY, true)
    Cmd(C.VIS, T, 0, true)
  end

-- Player page block (plate_pages.lua)
  function G.gauge_copy_count(layer)
    if G.gaugeCopyCounts == nil then
      -- the Trayectoria bands' layer stays in the page objects (its page is a declared mod page)
      G.CSB = G.CSB or 447684455
      G.gaugeCopyCounts = {[G.TAG] = 1, [G.PT] = 5, [G.PTRULE] = 1, [G.SXBAR] = 1, [G.SXPLATE] = 1, [G.CSB] = 2,
        [G.FBADGE] = 3}
    end
    return G.gaugeCopyCounts[layer]
  end
  function G.is_gauge_copy_placed(layer, instance)
    if layer == G.PT and instance == 0 and G.emptyOn then
      return true
    end
    return G.ready[layer * 16 + instance] == true
  end
  function G.hide_unplaced_gauge_copies()
    G.gauge_copy_count(G.TAG)
    for layer, count in pairs(G.gaugeCopyCounts) do
      if Exists(layer) then
        for instance = 0, count - 1 do
          if not G.is_gauge_copy_placed(layer, instance) and Cmd(C.IS_OPEN, layer, instance) == true then
            Cmd(C.VIS, layer, instance, false)
          end
        end
      end
    end
  end
  function G.forget_gauge_copy(layer, instance)
    if type(instance) ~= "number" or G.gauge_copy_count(layer) == nil then
      return
    end
    G.ready[layer * 16 + instance] = false
    if layer == G.PT and instance == 0 then
      G.emptyOn = false
    elseif layer == G.FBADGE then
      G.fbKey = nil
    end
    Cmd(C.VIS, layer, instance, false)
  end

-- Player page block (plate_pages.lua)
  VRFW.pointer = VRFW.pointer or {}
  VRFW.pointer.new = VRFW.pointer.new or function()
    local P = {zones = {}, on = false, x = nil, y = nil, hot = nil, prev = {}, edge_t = 0, REPEAT = 10}
    local MOVED, POS, GPOS, CHECK, CTRL = 3272825600, 558229292, 4002164178, 4265778440, 1332654303
    local LEFT, CLICK = 749879980 --[[CMD_VRFW_MOUSE_LEFT]], 1651523701 --[[CMD_ENTER_CLICK]]
    local W_UP, W_DOWN = 2649361876 --[[CMD_VRFW_WHEEL_UP]], 1098743808 --[[CMD_VRFW_WHEEL_DOWN]]
    local NAV = {1197218715, 3259546669, 2765147006, 2075023265} -- CMD_UP / DOWN / LEFT / RIGHT
    local CTRLS = {CTRL, 2748927068 --[[analog-move control: the stick's menu moves]]}
    local function M(cmd, ...)
      local ok, a, b = pcall(funcLuaMenuCommand, cmd, ...)
      if ok then return a, b end
      return nil
    end
    local function In(cmd, ctrl)
      local ok, r = pcall(funcLuaCommand, CHECK, ctrl or CTRL, cmd)
      return ok and r == true
    end
    local function Edge(cmd, ctrl)
      local key = ctrl and (tostring(ctrl) .. ":" .. tostring(cmd)) or cmd
      local now = In(cmd, ctrl)
      local was = P.prev[key]
      P.prev[key] = now
      return now and not was
    end
    --- Starts a new list of pointer zones for this frame.
    function P.begin()
      P.zones = {}
    end
    --- Adds a zone by top-left corner and size; `id` is what P.at answers, `edge` as in P.poll.
    function P.rect(x, y, w, h, id, edge)
      P.zones[#P.zones + 1] = {x, y, x + w, y + h, id = id, edge = edge}
    end
    --- Adds a zone by centre and half sizes; `id` and `edge` as in P.rect.
    function P.box(cx, cy, hw, hh, id, edge)
      P.zones[#P.zones + 1] = {cx - hw, cy - hh, cx + hw, cy + hh, id = id, edge = edge}
    end
    --- Adds a zone that follows instance idx of a layer, with half sizes hw and hh.
    function P.inst(layer, idx, hw, hh, id, edge)
      P.zones[#P.zones + 1] = {layer = layer, idx = idx, hw = hw, hh = hh, id = id, edge = edge}
    end
    --- The pointer position: x, y, or nil when it is not available.
    function P.position()
      local x, y = M(POS)
      if type(x) == "number" and type(y) == "number" then return x, y end
      return nil
    end
    --- The topmost zone under (x, y), or under the last pointer position; nil when there is none.
    function P.at(x, y)
      if x == nil then x, y = P.x, P.y end
      if x == nil then return nil end
      for i = #P.zones, 1, -1 do
        local z = P.zones[i]
        if z.layer ~= nil then
          local gx, gy = M(GPOS, z.layer, z.idx)
          if type(gx) == "number" and type(gy) == "number" and math.abs(x - gx) <= z.hw and math.abs(-y - gy) <= z.hh then
            return z
          end
        elseif x >= z[1] and x < z[3] and y >= z[2] and y < z[4] then
          return z
        end
      end
      return nil
    end
    -- (Enter / A with the pointer resting on empty space is a key Accept on the current selection)
    --- True when this press belongs to the pointer: a left click, or a click over a zone while the pointer is on.
    function P.owns()
      return In(LEFT) or (P.on and In(CLICK) and P.at() ~= nil)
    end
    --- Clears the hovered zone.
    function P.forget()
      P.hot = nil
    end
    --- Hands the cursor to the keys for this frame: pointer off, hover cleared, position remembered.
    function P.key_step()
      P.on, P.hot = false, nil
      local x, y = P.position()
      if x ~= nil then P.x, P.y = x, y end
    end
    --- Clears the zones, the hover and the edge state, and remembers the pointer position.
    function P.reset()
      P.zones, P.on, P.hot, P.prev, P.edge_t = {}, false, nil, {}, 0
      P.x, P.y = P.position()
      for _, c in ipairs({LEFT, CLICK, W_UP, W_DOWN}) do Edge(c) end
      for _, ctrl in ipairs(CTRLS) do
        for _, c in ipairs(NAV) do Edge(c, ctrl) end
      end
    end
    --- One frame of pointer input; answers this frame's event table.
    function P.poll()
      local ev = {}
      local x, y = P.position()
      if x ~= nil then
        local moved = M(MOVED) == true
        if not moved and P.x ~= nil and (math.abs(x - P.x) > 1 or math.abs(y - P.y) > 1) then
          moved = true
        end
        P.x, P.y = x, y
        if moved then
          P.on, ev.moved = true, true
        end
      end
      for _, ctrl in ipairs(CTRLS) do
        for _, c in ipairs(NAV) do
          if Edge(c, ctrl) then
            ev.keys = true
          end
        end
      end
      if ev.keys and not ev.moved then
        P.on = false
      end
      local left, click = Edge(LEFT), Edge(CLICK)
      if left then
        P.on, ev.left = true, true
      end
      local z = P.on and P.at() or nil
      local id = z and z.id or nil
      ev.changed = id ~= P.hot
      P.hot, ev.hot = id, id
      if z ~= nil and (ev.moved or left) then
        ev.hover = id
      end
      if left then
        if z ~= nil then
          ev.click = id
        else
          ev.miss = true                 -- a mouse click on empty space: nothing
        end
      elseif click and P.on then
        if z ~= nil then
          ev.click = id
        else
          P.on, P.hot = false, nil
        end
      end
      if In(W_DOWN) then
        ev.wheel = 1
      elseif In(W_UP) then
        ev.wheel = -1
      end
      if z ~= nil and z.edge ~= nil then
        P.edge_t = P.edge_t - 1
        if P.edge_t <= 0 then
          ev.edge, P.edge_t = z.edge, P.REPEAT
        end
      else
        P.edge_t = 0
      end
      return ev
    end
    return P
  end
  G.PTR_DOT = {x0 = 1321, dx = 28, y = 895, h = 50}
  G.PTR_Q, G.PTR_E = {1258, 893, 62, 54}, {1551, 893, 56, 54}
  G.PTR_R3 = {1708, 893, 44, 54}
  G.PTR_FORM = {1706, 893, 214, 54}     -- the hint on the dots row from x 1713 (layout)
  G.BANKS = {1981996040, 3358148956}
  function G.ptr_go(target, dir)
    local Lc = VRFW.host.command
    if type(target) == "number" then
      G.gotoT = 3                          -- the plate's own step too (a bank in its list view steps the plate)
      if VRFW.player_pages ~= nil then
        VRFW.player_pages.go_to(target)
      end
    end
    for pass = 1, 2 do
      for _, m in ipairs(pass == 1 and G.BANKS or G.PARENTS) do
        if Lc(264888438, m) == true then
          Lc(830228314, m, "CharacterReforgedPlayerPagePointerPage", target, dir, pass == 1)
          Lc(C.LOG, "PlayerPage pointer page", string.format("%08X", m), tostring(target), dir)
          return
        end
      end
    end
    pcall(dir > 0 and SetPersonalPlateNextPage or SetPersonalPlatePrevPage)
  end
  function G.ptr_form()
    local M = CharacterReforged.page_model
    if G.ptype == G.HIPER_TYPE then        -- the Hiper page, Normal / the shown aura's form
      G.hiper_toggle("click")
      return
    end
    if G.ptype == CharacterReforged.PLAYER_PAGE_STATS_TYPE then  -- ATRIBUTOS, Normal / Miximax
      G.mx_toggle("click")
      return
    end
    if G.view_offered() then
      pcall(M.open_view, "click")
      return
    end
    if type(M) ~= "table" or M.phase ~= "ready" or CharacterReforged.PAGE_MODEL_PAGE_FORMS ~= true or type(M.forms) ~= "table"
        or #M.forms <= 1 or type(M.mark_fresh) ~= "function" then
      return
    end
    M.last = M.tick or 0
    M.fidx = (M.fidx or 1) % #M.forms + 1
    pcall(funcLuaCommand, 1917805374, 2629173176)   -- sy0009, as R3
    M.mark_fresh()
  end
  function G.pointer()
    if G.gotoT ~= nil then
      G.gotoT = G.gotoT - 1
      if G.gotoT <= 0 then
        G.gotoT = nil
        if VRFW.player_pages ~= nil then
          VRFW.player_pages.go_to(nil)
        end
      end
    end
    local up = On() and G.ptype ~= nil and Exists(G.STATUS) and Cmd(C.IS_VIS, G.STATUS, 0) == true
      and not (type(BetterQoL) == "table" and type(BetterQoL.passive_config_plate) == "table" and BetterQoL.passive_config_plate.co ~= nil)
    if not up then
      G.ptrUp = false
      return
    end
    G.ptr = G.ptr or VRFW.pointer.new()
    local P = G.ptr
    if not G.ptrUp then
      G.ptrUp = true
      P.reset()
    end
    P.begin()
    local D = G.PTR_DOT
    local pages = G.slot_pages()
    for s = 1, G.DOTS_MAX do
      if pages[s] ~= nil then
        P.rect(D.x0 + D.dx * (s - 1) + 2, D.y, D.dx, D.h, s)
      end
    end
    P.rect(G.PTR_Q[1], G.PTR_Q[2], G.PTR_Q[3], G.PTR_Q[4], "q")
    P.rect(G.PTR_E[1], G.PTR_E[2], G.PTR_E[3], G.PTR_E[4], "e")
    local psub = G.ptype == 2 and not G.in_office()
    if psub then
      for k = 2, 1 + G.PSUB_N do
        P.rect(G.PSUB_DOT_X[k] + 2, D.y, D.dx, D.h, "p" .. (k - 2))
      end
      P.rect(G.PTR_R3[1], G.PTR_R3[2], G.PTR_R3[3], G.PTR_R3[4], "r3")
    end
    local forms = type(CharacterReforged.page_model) == "table" and type(CharacterReforged.page_model.forms) == "table" and #CharacterReforged.page_model.forms or 0
    if G.ptype == CharacterReforged.PLAYER_PAGE_DESCRIPTION_TYPE and not G.in_office() then
      local b = G.fbBox
      if G.view_offered() then
        P.rect(G.PTR_FORM[1], G.PTR_FORM[2], G.PTR_FORM[3], G.PTR_FORM[4], "form")
      elseif forms > 1 and b ~= nil then
        P.rect(b[1], b[2], b[3], b[4], "form")   -- the form badge (tiles + RS key)
      end
    elseif G.ptype == G.HIPER_TYPE and not G.in_office() and G.fbBox ~= nil
        and (G.hiperTgt ~= nil or G.hiperDouble == true) then
      local b = G.fbBox
      P.rect(b[1], b[2], b[3], b[4], "form")     -- the Hiper page's form badge
    elseif G.ptype == CharacterReforged.PLAYER_PAGE_STATS_TYPE and not G.in_office() and G.fbBox ~= nil and G.mx_avail() then
      local b = G.fbBox
      P.rect(b[1], b[2], b[3], b[4], "form")     -- ATRIBUTOS' Normal / Miximax badge
    end
    local ev = P.poll()
    local c = ev.click
    if c == nil then
      return
    end
    if type(c) == "number" then
      local cur = G.slot(G.ptype)
      local target = pages[c]
      if cur ~= nil and c ~= cur and target ~= nil then
        G.ptr_go(target, c > cur and 1 or -1)
      end
    elseif c == "q" or c == "e" then
      G.ptr_go(nil, c == "e" and 1 or -1)
    elseif c == "r3" or string.sub(c, 1, 1) == "p" then
      local n = c == "r3" and G.next_passive_sub_page() or tonumber(string.sub(c, 2))
      if n ~= nil and n ~= G.psub then
        G.show_passive_sub_page(n)
      end
    elseif c == "form" then
      G.ptr_form()
    end
  end

  local function Description(on)
    on = on and not G.in_office()           -- over the transfer office: its own description only
    Cmd(C.NODE_VIS, G.PLATE, G.N_EXPLAIN, on, 0)
    Cmd(C.TEXT_VIS, G.PLATE, G.N_EXPLAIN, on, 0)
    if Cmd(C.IS_OPEN, G.BAND, 0) == true then
      Cmd(C.MESH, G.BAND, G.M_FLAVOR, on, 0)
    end
  end

  function G.apply(ptype)
    -- A form look belongs to the page that chose it.
    if G.ptype ~= nil and ptype ~= G.ptype and type(CharacterReforged.page_model) == "table" and type(CharacterReforged.page_model.reset_form) == "function" then
      pcall(CharacterReforged.page_model.reset_form, "page " .. tostring(G.ptype) .. " -> " .. tostring(ptype), true)
    end
    G.ptype = ptype
    CharacterReforged.PAGE_MODEL_PAGE_OK = true                -- the model on every page, behind the content
    CharacterReforged.PAGE_MODEL_PAGE_FORMS = (ptype == CharacterReforged.PLAYER_PAGE_DESCRIPTION_TYPE)   -- R3 cycles the forms on PERFIL
    local desc, stats, moves = ptype == CharacterReforged.PLAYER_PAGE_DESCRIPTION_TYPE, ptype == CharacterReforged.PLAYER_PAGE_STATS_TYPE, ptype == 1
    if desc or stats then
      pcall(SetVisibleSkillItemLayer, false)
    end
