        local t = {}
        for k, v in pairs(IC[part[1]]) do
          t[k] = v
        end
        for k, v in pairs(over) do
          t[k] = v
        end
        IC[part[1]] = t
      end
    end
    if IC.light_text then
      IC.effect.styles.ink = IC.effect.styles.white
      for name, sprite in pairs(IC.effect.sprites_on_dark) do
        IC.effect.sprites[name] = sprite
      end
    end
    IC.layers_set = {}
    for _, l in ipairs(IC.layers or {IC.layer}) do
      IC.layers_set[l] = true
    end
    G.item_card_layer = IC.layer
    local HostHide = G.host_hide
    G.host_hide = function(...)
      if HostHide ~= nil then
        HostHide(...)
      end
      for _, l in ipairs({G.EQ_BODY, G.EQ_ICON, G.EQ_DOTS, G.EQ_YPAGE}) do
        if l ~= nil and Exists(l) then
          for k = 0, 63 do
            if Cmd(C.IS_OPEN, l, k) == true then
              Cmd(C.VIS, l, k, false)
            end
          end
        end
      end
    end

    -- Writes once to loader.log with the call's place (VRFW.debug.traceback).
    if CharacterReforged.PLAYER_PAGE_PCALL == nil then
      local raw = pcall
      CharacterReforged.PLAYER_PAGE_PCALL = raw
      pcall = function(f, ...)
        if f == nil then
          if not CharacterReforged.PLAYER_PAGE_NIL_LOGGED then
            CharacterReforged.PLAYER_PAGE_NIL_LOGGED = true
            local dbg = rawget(_ENV, "VRFW.debug")
            local where = (type(dbg) == "table" and type(dbg.traceback) == "function") and dbg.traceback("", 2) or "?"
            raw(funcLuaCommand, C.LOG, "PlayerPage pcall of a nil function skipped", tostring(where))
          end
          return false, "attempt to call a nil value"
        end
        return raw(f, ...)
      end
    end
    function G.item_card_on()
      return On() and CharacterReforged.PLAYER_PAGE_HOST_OFF ~= true and IC.on ~= false
    end

    local function Fill(template, args)
      return (string.gsub(tostring(template), "{(%w+)}", function(k)
        local v = args[k]
        return v ~= nil and tostring(v) or ""
      end))
    end

    function G.signed_bonus(s)
      local head, minus, num, tail = string.match(s, "^(.-)%+(%-?)(%d+)(.*)$")
      if head == nil then
        return (string.gsub(s, "%+%-", "-"))
      end
      if minus == "-" then
        return head .. IC.minus_colour .. "-" .. num .. "[C]" .. tail
      end
      return head .. IC.plus_colour .. "+" .. num .. "[C]" .. tail
    end

    G.icPage, G.icPages, G.icBonus = 1, {}, ""
    function G.item_card_paged()
      return type(IC.paged) == "table" and #G.icPages > 1
    end
    -- Returns the card's rect.
    function G.item_card_rect()
      local P = IC.paged
      if IC.card_h ~= nil then
        return {IC.rect[1], IC.rect[4] - IC.card_h, IC.rect[3], IC.rect[4]}, P.max_rows
      end
      local h = P.first_row + (P.max_rows - 1) * P.row_pitch + P.bottom
      return {IC.rect[1], IC.rect[2], IC.rect[3], IC.rect[2] + h}, P.max_rows
    end

    function G.item_card_set_page(item)
      local set = IC.set_command ~= nil and VRFW.host.command(IC.set_command, item, (not IC.no_player and type(G.hdl) == "number") and G.hdl or 0)
      if type(set) ~= "table" or type(set.members) ~= "table" then
        return nil
      end
      local worn = {}
      if not IC.no_player and type(G.hdl) == "number" and type(GetCharaEquipmentIds) == "function" then
        local ok, ids = pcall(GetCharaEquipmentIds, G.hdl)
        for _, id in ipairs(ok and type(ids) == "table" and ids or {}) do
          worn[id] = true
        end
      end
      if type(G.icWornSwap) == "table" then          -- a preview: the hovered item in the slot's item's place
        if G.icWornSwap.from ~= nil then
          worn[G.icWornSwap.from] = nil
        end
        worn[G.icWornSwap.to] = true
      end
      local rows, wornSlot, nworn, nslots = {}, {}, 0, 0
      local count = tonumber(set.count) or #set.members
      for k = 1, count do
        local id = set.members[k]
        if id ~= nil then
          local slot = G.item_card_slot(id)
          if slot ~= nil then
            if rows[slot] == nil then
              rows[slot] = {}
              nslots = nslots + 1
            end
            table.insert(rows[slot], {id, worn[id] == true})
            if worn[id] and not wornSlot[slot] then
              wornSlot[slot] = true
              nworn = nworn + 1
            end
          end
        end
      end
      -- progress by pieces = the set's slots covered (one item per slot), as Better Equipment counts the bonus tiers
      G.icSet = {rows = rows, worn = wornSlot, nworn = nworn, nslots = nslots}
      -- the pieces that count for this set (a piece counts for one set only), then its other sets on the same row
      local template = IC.no_player and set.title_any or set.title
      local title = Fill(template or set.title, {set = set.name, worn = tonumber(set.worn) or nworn, count = nslots})
      if type(set.also) == "string" and set.also ~= "" then
        title = title .. "  " .. set.also
      end
      G.icSetTitle = title
      return G.item_card_centred(title)
    end

-- Player page block (plate_pages.lua)
    G.EQ_BODY, G.EQ_ICON = 2973728099, 2281008258
    table.insert(G.HOST_LAYERS, G.EQ_BODY)
    table.insert(G.HOST_LAYERS, G.EQ_ICON)
    G.icReady = {}

    -- Draws the body.
    function G.item_card_body(rect, show)
      local B = G.EQ_BODY
      if not Exists(B) then
        return true
      end
      if not show then
        if Cmd(C.IS_OPEN, B, 0) == true then
          Cmd(C.VIS, B, 0, false)
        end
        return true
      end
      if not Ready(B, 0) then
        G.icReady[B] = nil
        return false
      end
      if not G.icReady[B] then
        G.icReady[B] = true
        for _, m in ipairs({G.M_PORTRAIT, G.M_BAND, G.M_FLAVOR, G.M_PARAM[1], G.M_PARAM[2]}) do
          Cmd(C.MESH, B, m, false, 0)
        end
        Cmd(C.TEXT_VIS, B, G.N_EXPLAIN, false, 0)
        Cmd(C.SPRITE, B, G.TX_T1101, G.SP_BAND, G.SP_BODY, 0, 0)
      end
      -- Uses the layer where the stats panel's body layer (G.BAND, the same object) is, so the band layout's node is read there.
      if Exists(G.BAND) and Cmd(C.IS_OPEN, G.BAND, 0) == true then
        local ok, x, y, z = pcall(funcLuaMenuCommand, 4002164178 --[[a layer instance's global position]], G.BAND, 0)
        if ok and type(x) == "number" and type(y) == "number" then
          Cmd(C.POS, B, x, y, tonumber(z) or 0, 0)
        end
        if not G.icBodyLogged then
          G.icBodyLogged = true
          pcall(funcLuaCommand, C.LOG, "PlayerPage item card body at", tostring(ok and x), tostring(ok and y))
        end
      end
      Cmd(C.NODE_POS, B, 0, G.M_PAGE, 0, rect[1] - 1435)
      Cmd(C.NODE_POS, B, 0, G.M_PAGE, 1, 560 - rect[2])
      Cmd(C.NODE_SCALE, B, 0, G.M_PAGE, rect[3] - rect[1], rect[4] - rect[2])
      Cmd(C.MESH, B, G.M_PAGE, true, 0)
      Cmd(C.VIS, B, 0, true)
      return true
    end

    G.EQ_ICON_MESHES = {2511236049, 2885220123, 303536660, 2334051246,
      2203859798, 441805548, 1202991162, 1139638886,
      1087832946, 1228576956, 2037408502, 132349475, 2634282032,
      2787359195}
    G.EQ_ICON_TEXTS = {456522680, 3138144965}
    G.EQ_ICON_PRIMS = {3974820126, 3334923667}           -- the card's E / stock numbers
    local M_SLOT, M_ITEM = 2885220123, 303536660

    local function IconSlot(k, x, y, kind, value, worn, scale)
      scale = scale or 1
      local L, S = G.EQ_ICON, IC.set_icons
      if not Ready(L, k) then
        G.icReady[L * 16 + k] = nil
        return false
      end
      if not G.icReady[L * 16 + k] then
        G.icReady[L * 16 + k] = true
        for _, m in ipairs(G.EQ_ICON_MESHES) do
          Cmd(C.MESH, L, m, false, k)
        end
        for _, t in ipairs(G.EQ_ICON_TEXTS) do
          Cmd(C.TEXT_VIS, L, t, false, k)
        end
        for _, p in ipairs(G.EQ_ICON_PRIMS) do
          Cmd(C.PRIM_VIS, L, k, p, false)
        end
        Cmd(C.NODE_POS, L, k, IC.base, 0, 0)
        Cmd(C.NODE_POS, L, k, IC.base, 1, 0)
      end
      Cmd(C.MESH, L, M_SLOT, false, k)
      Cmd(C.MESH, L, M_ITEM, false, k)
      for _, t in ipairs(G.EQ_ICON_TEXTS) do
        Cmd(C.TEXT_VIS, L, t, false, k)
      end
      local E = IC.effect
      local under, over = E.prio_under, E.prio_over
      if G.icPrioBase ~= nil then
        under, over = G.icPrioBase + 2, G.icPrioBase + 4
      end
      Cmd(1491630496, L, k, (type(value) == "table" and value.under) and under or over, true)
      if kind == "text" then
        -- Centres the text vertically.
        local st = E.styles[value.style] or E.styles.white
        local sc = value.scale or 1
        Cmd(C.SCALE, L, sc, sc, 1, k)
        local top = y - st.box_h * sc / 2 + (st.dy or 0) * sc
        Cmd(C.POS, L, x - st.at[1] * sc, -top - st.at[2] * sc, 0, k)
        Cmd(C.SET_TEXT, L, st.node, value.text, k)
        Cmd(C.TEXT_VIS, L, st.node, true, k)
        Cmd(C.VIS, L, k, true)
        return true
      end
      Cmd(C.SCALE, L, 1, 1, 1, k)
      Cmd(C.POS, L, x, -y, 0, k)
      if kind == "sprite" then
        Cmd(C.SPRITE, L, value[1], value[2], S.slot_swap, 0, k)
        Cmd(C.NODE_POS, L, k, M_SLOT, 0, 0)
        Cmd(C.NODE_POS, L, k, M_SLOT, 1, 0)
        Cmd(C.NODE_SCALE, L, k, M_SLOT, value[3], value[4])
        Cmd(C.MESH, L, M_SLOT, true, k)
        Cmd(C.VIS, L, k, true)
        return true
      end
      if kind == "badge" or kind == "slot" then
        local atlas, sprite, w, h
        if kind == "badge" then
          local B = IC.badges
          atlas, sprite, w, h = B.atlas, value, B.size[1], B.size[2]
        elseif worn then
          atlas, sprite, w, h = S.worn_atlas, S.slot_worn_sprites[value], S.slot_size[1] * scale, S.slot_size[2] * scale
        else
          atlas, sprite, w, h = S.slot_atlas, S.slot_sprites[value], S.slot_size[1] * scale, S.slot_size[2] * scale
        end
        Cmd(C.SPRITE, L, atlas, sprite, S.slot_swap, 0, k)
        Cmd(C.NODE_POS, L, k, M_SLOT, 0, 0)
        Cmd(C.NODE_POS, L, k, M_SLOT, 1, 0)
        Cmd(C.NODE_SCALE, L, k, M_SLOT, w, h)
        Cmd(C.MESH, L, M_SLOT, true, k)
      else
        local n = S.size * scale
        funcLuaMenuCommand(3508889864 --[[the item icon]], L, k, M_ITEM, 1875672568 --[[icon_item_dmy01]], value)
        Cmd(C.NODE_POS, L, k, M_ITEM, 0, 0)
        Cmd(C.NODE_POS, L, k, M_ITEM, 1, 0)
        Cmd(C.NODE_SCALE, L, k, M_ITEM, n, n)
        Cmd(C.MESH, L, M_ITEM, true, k)
      end
      Cmd(C.VIS, L, k, true)
      return true
    end

    -- Shows the shown page's icons (the set grid with its slot icons, the affinity badge), else none.
    G.EQ_DOTS = 4086241936
    table.insert(G.HOST_LAYERS, G.EQ_DOTS)
    G.EQ_YPAGE = 3144664112
    if IC.pager ~= nil and IC.pager.style == "ycycle" then
      table.insert(G.HOST_LAYERS, G.EQ_YPAGE)
    end
    do
      PlayerPageWrap("OnSetupLayer", function(orig)
        return function(a1, a2, ...)
          local r = Pack(orig(a1, a2, ...))
          if a1 == G.EQ_ICON or a1 == G.EQ_DOTS or a1 == G.EQ_YPAGE then
            Cmd(C.VIS, a1, a2 or 0, false)
            G.icReady[a1 * 16 + (a2 or 0)] = nil   -- a new instance (a group opened again): its meshes set up again
          end
          return table.unpack(r, 1, r.n)
        end
      end)
    end
    function G.item_card_pager(n)
      if G.icPager == nil and type(VRFW.pager) == "table" and type(VRFW.pager.new) == "function" then
        G.icPager = VRFW.pager.new({layer = G.EQ_DOTS, name = "item card", style = IC.pager.style, guide = G.EQ_YPAGE,
          prio = G.icPrioBase ~= nil and G.icPrioBase + 6 or nil, reopen = function()
            return not G.hostShut
          end})
      end
      local R = G.icPager
      if R == nil then
        return true
      end
      if n == nil or n < 2 then
        R:hide()
        return true
      end
      local nextPage = G.icPage % n + 1
      local placed = R:show(n, G.icPage, IC.pager.at[1], -IC.pager.at[2], G.icPageNames ~= nil and G.icPageNames[nextPage] or nil)
      -- Handles a card placed elsewhere than the object's layout.
      if placed and IC.pager.pill_shift ~= nil then
        Cmd(C.POS, G.EQ_YPAGE, IC.pager.pill_shift[1], IC.pager.pill_shift[2], 0, 0)
        if G.icPrioBase ~= nil then
          Cmd(1491630496, G.EQ_YPAGE, 0, G.icPrioBase + 6, true)
        end
      end
      return placed
    end

    function G.item_card_page_icons()
      -- Handles the host menu closing.
      if G.hostShut then
        if not G.icShutLogged then
          G.icShutLogged = true
          pcall(funcLuaCommand, C.LOG, "PlayerPage item card: drawn after the host shut, skipped")
        end
        return true
      end
      local L, S = G.EQ_ICON, IC.set_icons
      if not Exists(L) then
        return true
      end
      local used, done = 0, true
      local shown = G.item_card_on() and #G.icPages > 0 and Exists(IC.layer) and Cmd(C.IS_VIS, IC.layer, 0) == true
      local on = shown and G.icSetPage ~= nil and G.icPage == G.icSetPage and type(G.icSet) == "table"
      if shown and (IC.text_on_icons or G.icStatPage ~= nil) then
        local okT, items = pcall(G.item_card_text_items, G.item_card_rect())
        for _, it in ipairs(okT and items or {}) do
          if used < (S.page_instances or S.instances) then
            done = IconSlot(used, it.x, it.y, it.kind, it.value) and done
            used = used + 1
          end
        end
      end
      if shown and G.icEffect ~= nil and G.icEffectPage ~= nil and G.icPage == G.icEffectPage then
        local okI, items = pcall(G.item_card_effect_items, G.item_card_rect())
        for _, it in ipairs(okI and items or {}) do
          if used < (S.page_instances or S.instances) then
            done = IconSlot(used, it.x, it.y, it.kind, it.value) and done
            used = used + 1
          end
        end
      end
      if on then
        -- Collects the groups of the slots the set has, left to right.
        local rect = G.item_card_rect()
        local groups, width = {}, 0
        for slot = 1, #S.slot_sprites do
          local pieces = G.icSet.rows[slot]
          if pieces ~= nil and #pieces > 0 then
            groups[#groups + 1] = {slot = slot, pieces = pieces}
            width = width + S.slot_size[1] + #pieces * (S.gap + S.size)
          end
        end
        width = width + math.max(0, #groups - 1) * S.group_gap
        local room = (rect[3] - rect[1]) - 2 * S.margin
        local f = width > 0 and math.min(1, room / width) or 1
        local x = rect[1] + ((rect[3] - rect[1]) - width * f) / 2
        local P = IC.paged
        local cy = rect[2] + (S.row_cy or ((P.first_row + (P.first_row + (P.max_rows - 1) * P.row_pitch)) / 2))
        local top = cy - S.size * f / 2
        for _, grp in ipairs(groups) do
          if used < (S.page_instances or S.instances) then
            done = IconSlot(used, x, top, "slot", grp.slot, G.icSet.worn[grp.slot] == true, f) and done
            used = used + 1
          end
          x = x + S.slot_size[1] * f
          for _, it in ipairs(grp.pieces) do
            x = x + S.gap * f
            if used < (S.page_instances or S.instances) then
              done = IconSlot(used, x, top, "item", it[1], it[2], f) and done
              used = used + 1
            end
            x = x + S.size * f
          end
          x = x + S.group_gap * f
        end
      end
      for k = used, (S.page_instances or S.instances) - 1 do
        if Cmd(C.IS_OPEN, L, k) == true then
          Cmd(C.VIS, L, k, false)
        end
      end
      if not G.item_card_pager(shown and #G.icPages or nil) then
        done = false
      end
      if not done then
        G.itemCardPending = true
      end
      return done
    end

    -- the width in px of `text` in the card's bonus box (CMND_GET_MENU_TEXT_RECT_SIZE), nil = no answer
    local function TextWidth(text)
      local ok, w = pcall(funcLuaMenuCommand, 3549540977, IC.layer, 0,
        3138144965 --[[_text_parameter01]], text)
      w = ok and tonumber(w) or nil
      return (w ~= nil and w > 0) and w or nil
    end

    -- row 1 the item's passive chip, position / element badges and raised stats
    local function EffWidth(text, style)
      local E = IC.effect
      local st = E.styles[style] or E.styles.white
      local ok, w = pcall(funcLuaMenuCommand, 3549540977, IC.layer, 0, st.node, text)
      w = ok and tonumber(w) or nil
      if w == nil or w <= 0 then
        w = #text * st.char_px
      end
      return w
    end

    local function Spr(name)
      return {IC.effect.atlas, CALC_CRC(name)}
    end

    -- Returns the content of a chip.
    local function EffPieces(part, on)
      local E = IC.effect
      local p = {}
      if part.stat ~= nil then
        local n = E.stat_icons[part.stat]
        if n ~= nil then
          p[#p + 1] = {sprite = string.format(E.sprites.stat, n)}
        end
        local name = G.item_card_stat_name(part.stat_index) or part.stat_name or part.stat
        p[#p + 1] = {text = tostring(name)}
        p[#p + 1] = {text = tostring(part.value)}
        return p
      end
      if part.label ~= nil and (part.element ~= nil or part.family ~= nil) then
        p[#p + 1] = {text = tostring(part.label)}
        local el = part.element ~= nil and E.elements[part.element] or nil
        local ext = type(part.element_icon) == "table" and part.element_icon or nil
        if el ~= nil then
          p[#p + 1] = {sprite = string.format(on and E.sprites.element or E.sprites.element_off, el)}
        elseif ext ~= nil then
          p[#p + 1] = {atlas = ext.atlas, sprite_id = ext.sprite}
        elseif part.family ~= nil then
          p[#p + 1] = {text = tostring(part.family)}
        elseif part.element ~= nil then
          p[#p + 1] = {text = tostring(G.item_card_element_name(part.element) or part.element_name or part.element)}
        end
        p[#p + 1] = {text = tostring(part.value)}
        return p
      end
      p[#p + 1] = {text = tostring(part.text or "")}
      return p
    end

    G.statNames = G.statNames or {}
    function G.item_card_stat_name(si)
      si = tonumber(si)
      local id = si ~= nil and IC.effect.stat_texts[si + 1] or nil
      if id == nil then
        return nil
      end
      if G.statNames[si] == nil then
        local ok, t = pcall(funcLuaCommand, 4074371074 --[[the text of a text id]], id)
        local name = ok and type(t) == "string" and string.match(t, "^(.-)%s*%+") or nil
        G.statNames[si] = (name ~= nil and name ~= "") and name or false
      end
      return G.statNames[si] or nil
    end

    G.elementNames = G.elementNames or {}
    function G.item_card_element_name(element)
      local id = element ~= nil and IC.effect.element_texts[element] or nil
      if id == nil then
        return nil
      end
      if G.elementNames[element] == nil then
        local ok, t = pcall(funcLuaCommand, 4074371074 --[[the text of a text id]], id)
        G.elementNames[element] = (ok and type(t) == "string" and t ~= "") and t or false
      end
      return G.elementNames[element] or nil
    end

    local function PiecesWidth(pieces, style, sc)
      local E = IC.effect
      sc = sc or E.text_scale
      local w = 0
      for i, pc in ipairs(pieces) do
        if i > 1 then
          w = w + E.gap
        end
        if pc.sprite ~= nil or pc.sprite_id ~= nil then
          w = w + E.icon
        else
          w = w + EffWidth(pc.text, style) * sc
        end
      end
      return w
    end

    -- the pieces drawn from x at centre y (text colour tag `tag`)
    local function DrawPieces(out, pieces, x, y, tag, style, sc)
      local E = IC.effect
      sc = sc or E.text_scale
      for i, pc in ipairs(pieces) do
        if i > 1 then
          x = x + E.gap
        end
        if pc.sprite ~= nil or pc.sprite_id ~= nil then
          local sp = pc.sprite_id ~= nil and {pc.atlas, pc.sprite_id} or Spr(pc.sprite)
          out[#out + 1] = {kind = "sprite", x = x, y = y - E.icon / 2, value = {sp[1], sp[2], E.icon, E.icon}}
          x = x + E.icon
        else
          local t = pc.tag or tag
          out[#out + 1] = {kind = "text", x = x, y = y, value = {text = t .. pc.text .. (t ~= "" and "[C]" or ""),
            style = style, scale = sc}}
          x = x + EffWidth(pc.text, style) * sc
        end
      end
      return x
    end

    local function Section(out, x, y, sprite)
      local E = IC.effect
      local sp = Spr(sprite)
      out[#out + 1] = {kind = "sprite", x = x, y = y - E.section / 2, value = {sp[1], sp[2], E.section, E.section}}
      x = x + E.section + E.sep_gap
      local sv = Spr(E.sprites.sep)
      out[#out + 1] = {kind = "sprite", x = x, y = y - E.sep[2] / 2, value = {sv[1], sv[2], E.sep[1], E.sep[2]}}
      return x + E.sep[1] + E.sep_gap
    end

    local function Chip(out, x, y, w, sprite, h)
      local E = IC.effect
      local sp = Spr(sprite)
      h = h or E.chip_h
      out[#out + 1] = {kind = "sprite", x = x, y = y - h / 2, value = {sp[1], sp[2], w, h, under = true}}
    end

    function G.item_card_effect_items(rect)
      local E, F = IC.effect, G.icEffect
      local out = {}
      local x0, y0 = rect[1], rect[2]
      local r1, r2 = y0 + E.row1, y0 + E.row2
      local check = Spr(E.sprites.check)
      -- Draws row 1, left.
      local x = Section(out, x0 + E.left, r1, E.sprites.bond)
      if type(F.passive) == "table" then
        local pieces = EffPieces(F.passive, true)
        local pw = PiecesWidth(pieces, "white")
        local w = math.max(pw + 2 * E.chip_pad, E.passive_w)
        Chip(out, x, r1, w, E.sprites.chip_on)
        DrawPieces(out, pieces, x + (w - pw) / 2, r1, "", "white")
      end
      -- Draws row 1, right.
      local A = F.affinity
      if type(A) == "table" then
        x = Section(out, x0 + E.split, r1, E.sprites.emblem)
        local pos = A.position ~= nil and E.positions[A.position] or nil
        if pos ~= nil then
          local own = type(E.position_own) == "table" and E.position_own[A.position] or nil
          local sp = (A.pos_ok or IC.no_player)
            and (own ~= nil and Spr(own) or {IC.badges.atlas, CALC_CRC(string.format(E.sprites.position, pos))})
            or Spr(string.format(E.sprites.position_off, pos))
          out[#out + 1] = {kind = "sprite", x = x, y = r1 - E.badge[2] / 2, value = {sp[1], sp[2], E.badge[1], E.badge[2]}}
          if A.pos_ok then
            out[#out + 1] = {kind = "sprite", x = x + E.badge[1] - E.check / 2, y = r1 - E.badge[2] / 2 - E.check / 2,
              value = {check[1], check[2], E.check, E.check}}
          end
          x = x + E.badge[1] + E.gap
        end
        local el = A.element ~= nil and E.elements[A.element] or nil
        local ext = type(A.element_icon) == "table" and A.element_icon or nil
        if el == nil and ext == nil and A.element ~= nil then
          if pos ~= nil then
            x = DrawPieces(out, {{text = E.plus}}, x, r1, "", "ink") + E.gap
          end
          x = DrawPieces(out, {{text = G.item_card_element_name(A.element) or A.element}}, x, r1, "", "ink") + E.gap
        end
        if el ~= nil or ext ~= nil then
          if pos ~= nil then
            x = DrawPieces(out, {{text = E.plus}}, x, r1, "", "ink") + E.gap
          end
          local sp = el ~= nil and Spr(string.format((A.el_ok or IC.no_player) and E.sprites.element or E.sprites.element_off, el))
            or {ext.atlas, ext.sprite}
          out[#out + 1] = {kind = "sprite", x = x, y = r1 - E.icon / 2, value = {sp[1], sp[2], E.icon, E.icon}}
          if A.el_ok then
            out[#out + 1] = {kind = "sprite", x = x + E.icon - E.check / 2, y = r1 - E.icon / 2 - E.check / 2,
              value = {check[1], check[2], E.check, E.check}}
          end
          x = x + E.icon + E.gap
        end
        local pieces = {}
        for _, st in ipairs(type(A.stats) == "table" and A.stats or {}) do
          local n = E.stat_icons[st]
          if n ~= nil then
            pieces[#pieces + 1] = {sprite = string.format(E.sprites.stat, n)}
          end
        end
        pieces[#pieces + 1] = {text = tostring(A.text or "")}
        local rate = A.rate or ((A.pos_ok and A.el_ok) and "both" or (A.pos_ok and "one" or "none"))
        if IC.no_player then
          rate = "one"                         -- the requirement and both rates: the neutral (blue) chip
        end
        local chip = rate == "both" and E.sprites.chip_on or (rate == "one" and E.sprites.chip_blue or E.sprites.chip_off)
        local style = rate == "none" and "ink" or "white"   -- the off plate is light: the card's dark text
        local pw = PiecesWidth(pieces, style)
        local w = math.max(pw + 2 * E.chip_pad, E.affinity_w)
        local cx = math.max(x + E.gap, x0 + E.right - w)
        Chip(out, cx, r1, w, chip)
        DrawPieces(out, pieces, cx + (w - pw) / 2, r1, "", style)
      end
      -- Draws row 2.
      local S = G.icSet
      if type(F.tiers) == "table" and #F.tiers > 0 and type(S) == "table" then
        x = Section(out, x0 + E.left, r2, E.sprites.equip)
        local SI = IC.set_icons
        for slot = 1, #SI.slot_sprites do
          if S.rows[slot] ~= nil then
            local worn = S.worn[slot] == true
            local sp = worn and {SI.worn_atlas, SI.slot_worn_sprites[slot]} or {SI.slot_atlas, SI.slot_sprites[slot]}
            out[#out + 1] = {kind = "sprite", x = x, y = r2 - E.slot[2] / 2, value = {sp[1], sp[2], E.slot[1], E.slot[2]}}
            x = x + E.slot[1] + E.gap
          end
        end
        if not IC.no_player then
          x = DrawPieces(out, {{text = string.format("%d/%d", S.nworn or 0, S.nslots or 0)}}, x, r2, "", "ink")
        end
        x = x + E.tier_gap
        -- the tier chips to the right edge, the room split by their natural widths
        local nat, total = {}, 0
        for i, t in ipairs(F.tiers) do
          local on = not IC.no_player and (S.nworn or 0) >= (tonumber(t.pieces) or 99)
          local pieces = EffPieces(t.reward or {}, on)
          local style = (on or IC.no_player) and "white" or "ink"   -- the off plate is light: the card's dark text
          local w = math.max(PiecesWidth(pieces, style, E.tier_scale), E.tier_min) + 2 * E.chip_pad
          nat[i] = {pieces = pieces, w = w, on = on, style = style, need = tonumber(t.pieces) or 2}
          total = total + w
        end
        local room = (x0 + E.right) - x - (#nat - 1) * E.tier_gap
        for _, t in ipairs(nat) do
          local w = total > 0 and math.max(t.w, room * t.w / total) or t.w
          Chip(out, x, r2, w, t.on and E.sprites.chip_on or (IC.no_player and E.sprites.chip_blue or E.sprites.chip_off),
            E.tier_h)
          -- the reward centred, its text shrunk to fit the chip (down to tier_scale_min)
          local sc = E.tier_scale
          local pw = PiecesWidth(t.pieces, t.style, sc)
          if pw > w - 2 * E.chip_pad then
            sc = math.max(E.tier_scale_min, sc * (w - 2 * E.chip_pad) / pw)
            pw = PiecesWidth(t.pieces, t.style, sc)
          end
          DrawPieces(out, t.pieces, x + (w - pw) / 2, r2 + E.reward_dy, "", t.style, sc)
          local bx0, bx1 = x + E.bar_pad, x + w - E.bar_pad
          local bw = (bx1 - bx0 - E.bar_gap * (t.need - 1)) / t.need
          for i = 1, t.need do
            local name = i <= (S.nworn or 0) and (t.on and E.sprites.bar_white or E.sprites.bar_on) or E.sprites.bar_off
            local sp = Spr(name)
            out[#out + 1] = {kind = "sprite", x = bx0 + (i - 1) * (bw + E.bar_gap), y = r2 + E.bar_dy,
              value = {sp[1], sp[2], bw, E.bar_h}}
          end
          x = x + w + E.tier_gap
        end
      end
      return out
    end

    function G.item_card_centred(text)
      local B = IC.badges
      local w = TextWidth(text)
      local sw = TextWidth(string.rep(".", 10))
      local dot = TextWidth(string.rep(".", 10) .. string.rep(" ", 10))
      sw = (sw ~= nil and dot ~= nil and dot > sw) and (dot - sw) / 10 or B.space_px
      if w == nil then
        return text
      end
      local pad = ((IC.rect[3] - IC.rect[1]) / 2 - IC.text_x) - w / 2
      return string.rep(" ", math.max(0, math.floor(pad / sw + 0.5))) .. text
    end

    -- Returns the parts of the stat page (a card without a player).
    function G.item_card_stat_parts(item)
      local E, parts = IC.effect, {}
      for si = 0, 7 do
        local ok, has, v = pcall(funcLuaCommand, 2207870782, item, si)
        v = ok and has ~= false and tonumber(v) or 0
        local name = v ~= 0 and G.item_card_stat_name(si) or nil
        if name ~= nil then
          local key = IC.stat_by_index ~= nil and IC.stat_by_index[si + 1] or nil
          local icon = key ~= nil and E.stat_icons[key] or nil
          parts[#parts + 1] = {icon = icon ~= nil and string.format(E.sprites.stat, icon) or nil, name = name, value = v}
        end
      end
      return parts
    end

    -- Returns the shown page's texts drawn on the icon layer.
    function G.item_card_text_items(rect)
      local E, out = IC.effect, {}
      local width = rect[3] - rect[1] - 2 * (IC.set_icons.margin or 0)
      if G.icStatPage ~= nil and G.icPage == G.icStatPage then
        local sc, groups = E.stat_scale, {}
        for _, p in ipairs(G.icStats or {}) do
          local pieces = {}
          if p.icon ~= nil then
            pieces[#pieces + 1] = {sprite = p.icon}
          end
          pieces[#pieces + 1] = {text = p.name}
          pieces[#pieces + 1] = {text = (p.value > 0 and "+" or "-") .. tostring(math.abs(p.value)),
            tag = p.value > 0 and IC.plus_colour or IC.minus_colour}
          groups[#groups + 1] = pieces
        end
        local function Total(scale)
          local t = 0
          for _, g in ipairs(groups) do
            t = t + PiecesWidth(g, "ink", scale)
          end
          return t + math.max(0, #groups - 1) * E.stat_gap
        end
        local total = Total(sc)
        if total > width and total > 0 then
          sc = sc * width / total
          total = Total(sc)
        end
        local x = rect[1] + ((rect[3] - rect[1]) - total) / 2
        for _, g in ipairs(groups) do
          DrawPieces(out, g, x, rect[2] + E.stat_row, "", "ink", sc)
          x = x + PiecesWidth(g, "ink", sc) + E.stat_gap
        end
      elseif G.icSetPage ~= nil and G.icPage == G.icSetPage and type(G.icSetTitle) == "string" then
        local sc = E.title_scale
        local w = EffWidth(G.icSetTitle, "ink") * sc
        if w > width and w > 0 then
          sc = sc * width / w
          w = width
        end
        DrawPieces(out, {{text = G.icSetTitle}}, rect[1] + ((rect[3] - rect[1]) - w) / 2, rect[2] + E.title_y, "",
          "ink", sc)
      end
      return out
    end

    function G.item_card_effect_page(effect)
      if type(effect) == "string" then
        return effect
      end
      if type(effect) ~= "table" then
        return nil
      end
      local lines = {}
      for _, l in ipairs(type(effect.lines) == "table" and effect.lines or {}) do
        lines[#lines + 1] = tostring(l)
      end
      local a = effect.affinity
      if type(a) == "table" then
        local B = IC.badges
        local label = tostring(a.label or "")
        local row = label
        local sprite = a.position ~= nil and B.sprites[a.position] or nil
        if sprite ~= nil then
          local lw = label ~= "" and TextWidth(label) or 0
          local dots = TextWidth(string.rep(".", 10))
          local both = TextWidth(string.rep(".", 10) .. string.rep(" ", 10))
          local sw = (dots ~= nil and both ~= nil and both > dots) and (both - dots) / 10 or B.space_px
          local spaces = math.ceil((B.size[1] + 2 * B.gap) / sw)
          row = label .. string.rep(" ", spaces)
          local start = lw or #label * B.char_px
          G.icAffinity = {row = #lines + 1, sprite = sprite, x = start + (spaces * sw - B.size[1]) / 2}
        end
        if a.element ~= nil then
          row = row .. tostring(a.element) .. " "
        end
        lines[#lines + 1] = row .. tostring(a.text or "")
      end
      return table.concat(lines, "\n")
    end

    function G.item_card_pages(item)
      G.icPages, G.icSetPage, G.icStatPage, G.icPageNames, G.icSetTitle = {}, nil, nil, {}, nil
      if item == nil or item == 0 or not G.item_card_on() then
        return
      end
      G.icAffinity, G.icEffectPage, G.icEffect, G.icSet = nil, nil, nil, nil
      local hdl = (not IC.no_player and type(G.hdl) == "number") and G.hdl or 0
      local ok, set = pcall(G.item_card_set_page, item)
      local effect = IC.page_command ~= nil and VRFW.host.command(IC.page_command, item, hdl)
      local names = type(effect) == "table" and type(effect.page_names) == "table" and effect.page_names or {}
      if IC.stat_page then
        G.icStats = G.item_card_stat_parts(item)
        if #G.icStats > 0 then
          G.icPages[#G.icPages + 1] = ""
          G.icStatPage = #G.icPages
          G.icPageNames[#G.icPages] = names.stats
        end
      end
      if type(effect) == "table" and (type(effect.passive) == "table" or type(effect.affinity) == "table"
          or (type(effect.tiers) == "table" and #effect.tiers > 0)) then
        G.icEffect = effect
        G.icPages[#G.icPages + 1] = ""                    -- drawn by G.item_card_effect_items, no text
        G.icEffectPage = #G.icPages
        G.icPageNames[#G.icPages] = names.effect
      else
        local body = G.item_card_effect_page(effect)
        if body ~= nil and body ~= "" then
          G.icPages[#G.icPages + 1] = body
          G.icEffectPage = #G.icPages
        end
      end
      if ok and type(set) == "string" and set ~= "" then
        G.icPages[#G.icPages + 1] = IC.text_on_icons and "" or set
        G.icSetPage = #G.icPages
        G.icPageNames[#G.icPages] = names.set
      end
      if #G.icPages == 0 and not IC.stat_page then
        G.icStats = G.item_card_stat_parts(item)
        if #G.icStats > 0 then
          G.icPages[1] = ""
          G.icStatPage = 1
          G.icPageNames[1] = names.stats
        end
      end
      if G.icPage > #G.icPages then
        G.icPage = 1
      end
    end

    function G.item_card()
      local L, i = IC.layer, 0
      if not Exists(L) or Cmd(C.IS_OPEN, L, i) ~= true then
        G.itemCardPending = true
        return
      end
      G.itemCardPending = false
      if IC.relayout == false then
        return
      end
      local rect = G.item_card_rect()
      local h = rect[4] - rect[2]
      -- The base sits at the card's `anchor`.
      local ax, ay = IC.anchor[1], IC.anchor[2]
      local x0, y0 = rect[1], rect[2]
      Cmd(C.NODE_POS, L, i, IC.base, 0, x0 + ax - IC.root[1])
      Cmd(C.NODE_POS, L, i, IC.base, 1, IC.root[2] - (y0 + ay))
      for _, n in ipairs(IC.nodes) do
        local x, y, w, hh = n[2], n[3], n[4], n[5]
        if n.body then
          hh = h
        end
        Cmd(C.NODE_POS, L, i, n[1], 0, x - ax)
        Cmd(C.NODE_POS, L, i, n[1], 1, ay - y)
        if w ~= nil then
          Cmd(C.NODE_SCALE, L, i, n[1], w, hh)
        end
      end
      -- Hides the retail body mesh (its drop shadow).
      Cmd(C.MESH, L, IC.body_mesh, false, i)
      if IC.body_bottom == nil then
        G.try("item_card_body", nil, false)
      else
        local body = {rect[1], rect[2], rect[3], math.max(rect[4], IC.body_bottom)}
        if not G.item_card_body(body, true) then
          G.itemCardPending = true
        end
      end
      if not G.icDumped then
        G.icDumped = true
        G.try("item_card_dump")
      end
    end

    -- Dumps once.
    function G.item_card_dump()
      for _, n in ipairs(IC.dump or {}) do
        local ok, x, y = pcall(funcLuaMenuCommand, 499270986, IC.layer, 0, n[1])
        pcall(funcLuaCommand, C.LOG, "PlayerPage item card node", n[2], tostring(ok and x), tostring(ok and y))
      end
    end

-- Player page block (plate_pages.lua)
    -- Formats a stat change as a signed number.
    function G.signed_stat(v)
      v = tonumber(v) or 0
      if v > 2147483647 then
        v = v - 4294967296
      end
      if v < -9999 or v > 9999 then
        return 0
      end
      return v
    end
    -- The item's own stat (the game's equip parameter).
    local function ItemStat(it, si)
      if it == nil or it == 0 then
        return 0
      end
      local ok, has, v = pcall(funcLuaCommand, 2207870782, it, si)
      return ok and has ~= false and G.signed_stat(v) or 0
    end

    -- The 8 stat points the player page bonus hosts add (Equipment: affinity and sets, as the match adds them).
    local function StatBonus(item, slot)
      local page = CharacterReforged ~= nil and CharacterReforged.page or nil
      if type(G.hdl) ~= "number" or page == nil or page.stat_bonus == nil then
        return nil
      end
      local ok, b = pcall(page.stat_bonus, G.hdl, item, slot)
      return ok and type(b) == "table" and b or nil
    end

    -- Builds the stats panel's rows.
    function G.item_card_rows(item, base)
      local delta = nil
      if base ~= nil and base == item then
        base = nil
      end
      -- The bonus as worn now, then with the focused item worn (base nil: the focused item is the worn one, taken off).
      local now = StatBonus()
      local bonus = nil
      if now ~= nil then
        bonus = {}
        for g = 1, 8 do
          bonus[g] = G.signed_stat(now[G.STAT[g] + 1])
        end
      end
      -- The total of the item per stat is its stats plus the bonus points it brings into its slot, as the header boxes show.
      local total = nil
      if item ~= nil and item ~= 0 and G.item_card_on() and IC.rows ~= false then
        local slot = G.item_card_slot(item) or 0
        local empty = StatBonus(0, slot)
        local with = base == nil and now or StatBonus(item, slot)
        for si = 0, 7 do
          local brings = 0
          if empty ~= nil and with ~= nil then
            brings = G.signed_stat(with[si + 1]) - G.signed_stat(empty[si + 1])
          end
          local own = ItemStat(item, si) + brings
          local d = own
          if base ~= nil then
            local change = 0
            if now ~= nil and with ~= nil then
              change = G.signed_stat(with[si + 1]) - G.signed_stat(now[si + 1])
            end
            d = ItemStat(item, si) - ItemStat(base, si) + change
          end
          for g = 1, 8 do
            if G.STAT[g] == si then
              if d ~= 0 then
                delta = delta or {}
                delta[g] = d
              end
              if own ~= 0 then
                total = total or {}
                total[g] = own
              end
            end
          end
        end
      end
      G.rowTotal = total
      -- A stat shown at the game's minimum 1 can be below it (a drained stat); G.vals hold the bonus points too.
      local raw = nil
      if delta ~= nil and G.vals ~= nil and type(G.hdl) == "number" and CharacterReforged ~= nil
          and CharacterReforged.page ~= nil and CharacterReforged.page.stat_sum ~= nil then
        for g in pairs(delta) do
          local b = bonus ~= nil and bonus[g] or 0
          if (G.vals[g] or 0) - b <= 1 then
            local sum = CharacterReforged.page.stat_sum(G.hdl, G.STAT[g])
            raw = raw or {}
            raw[g] = sum ~= nil and sum + b or nil
          end
        end
      end
      G.rowDelta, G.rowOwn, G.rowRaw = delta, base == nil, raw
      G.try("item_card_luck_row")
    end

    -- Both kept at the game's minimum 1.
    function G.row_state(g, v)
      local d = G.rowDelta ~= nil and G.rowDelta[g] or nil
      if d == nil or d == 0 or type(v) ~= "number" then
        return nil
      end
      local sum = G.rowRaw ~= nil and G.rowRaw[g] or v
      local old, new = v, math.max(1, sum + d)
      if G.rowOwn then
        old, new = math.max(1, sum - d), v
      end
      if new == old then
        return nil
      end
      return old, new, new - old
    end

    -- Sets each row's number and outline by its state, drawn only when the state changes.
    G.rowMarkKey = {}
    function G.item_card_row_marks(change, shown)
      local R = IC.row_mark
      G.numBase = G.numBase or {}
      for g = 1, 8 do
        local c = change ~= nil and change[g] or nil
        local value = shown ~= nil and shown[g] or (G.vals[g] or 0)
        local key = tostring(c) .. "/" .. tostring(value)
        if key ~= G.rowMarkKey[g] and Exists(G.NUM) and Cmd(C.IS_OPEN, G.NUM, g - 1) == true then
          local k = G.GROUP_ROW[g]
          local gs, ga = G.gain_sprite(k)
          Cmd(C.SPRITE, G.BAR, ga, gs, G.GG.SLOT_GAIN_QUAD, 0, k)
          -- Reads the number's own colour once, before its first tint (CMND get prim colour, as the retail SetPrimitiveGrayout reads it).
          if G.numBase[g] == nil then
            local ok, r, gg, b = pcall(funcLuaMenuCommand, 3648327470 --[[get prim colour]], G.NUM, g - 1, R.number_style)
            if ok and type(r) == "number" and type(gg) == "number" and type(b) == "number" then
              G.numBase[g] = {r, gg, b}
            end
          end
          local tint = G.numBase[g]
          if c ~= nil then
            tint = R.colour[c > 0 and "raise" or "lower"]
          end
          if tint ~= nil then
            pcall(funcLuaMenuCommand, 855211291, G.NUM, g - 1, R.number_style, tint[1], tint[2], tint[3])
          end
          local prim = Cmd(1927054058, G.NUM, g - 1, R.number_style)
          Cmd(3609943765, G.NUM, g - 1, prim, value)
          Cmd(1233047821, G.NUM, g - 1, R.number_style, true)
          G.rowMarkKey[g] = key
        end
      end
    end

    -- Hides the icon layer's instances first..last that no part uses.
    local function HideUnused(L, first, last)
      for i = first, last do
        if Cmd(C.IS_OPEN, L, i) == true then
          Cmd(C.VIS, L, i, false)
        end
      end
      return Cmd(C.LOADING, L) ~= true
    end

    -- Draws the delta segments (G.bars hands their screen rects {x, y, w, h, raise} every frame).
    function G.delta_segment(segs)
      local R, S = IC.row_mark, IC.set_icons
      local parts = {}
      for _, sg in ipairs(segs or {}) do
        parts[#parts + 1] = string.format("%.0f %.0f %.0f %s", sg[1], sg[2], sg[3], tostring(sg[5]))
      end
      local key = table.concat(parts, "|")
      if key == G.segKey then
        return
      end
      local L = G.EQ_ICON
      if not Exists(L) then
        return
      end
      local B = R.delta.band
      local k, done = R.delta.first, true
      for _, sg in ipairs(segs or {}) do
        if sg[3] >= 1 and k < S.instances then
          local sp = {IC.effect.atlas, CALC_CRC(sg[5] and R.delta.raise or R.delta.lower), sg[3], sg[4] * B[2]}
          done = IconSlot(k, sg[1], sg[2] + sg[4] * B[1], "sprite", sp) and done
          k = k + 1
        end
      end
      done = HideUnused(L, k, R.delta.first + R.delta.count - 1) and done
      G.segKey = done and key or nil
    end

    -- Draws the delta labels on the icon layer's instances after the page icons, as small texts.
    function G.item_card_delta_labels(label)
      local L, S, R = G.EQ_ICON, IC.set_icons, IC.row_mark
      local parts = {}
      for g = 1, 8 do
        parts[g] = tostring(label ~= nil and label[g] or "")
      end
      local key = table.concat(parts, "|")
      if key == G.labelKey or not Exists(L) then
        return
      end
      local k = S.page_instances or S.instances
      local last = (IC.row_mark.delta.first or S.instances) - 1
      local done = true
      for g = 1, 8 do
        local v = label ~= nil and label[g] or nil
        if v ~= nil and v ~= 0 and k <= last then
          local row = G.GROUP_ROW[g]
          local col, r = math.floor(row / 4), row % 4
          -- the bars' origin (the chart base at G.CHART_AT), as the delta segments
          local x = G.CHART_AT[1] + G.ROW_X0[col] + R.label.dx
          local y = G.CHART_AT[2] - G.ROW_Y[r] + R.label.dy
          local text = (v > 0 and (R.label.plus .. "+") or (R.label.minus .. "-")) .. tostring(math.abs(v)) .. "[C]"
          done = IconSlot(k, x, y, "text", {text = text, style = "white", scale = R.label.scale}) and done
          k = k + 1
        end
      end
      done = HideUnused(L, k, last) and done
      G.labelKey = done and key or nil
    end

    -- This draws one grey plate per stat the focused item changes, with its stat icon and its signed total.
    function G.item_card_stat_boxes(total)
      local B = IC.stat_boxes
      local L = G.EQ_ICON
      if type(B) ~= "table" or not Exists(L) then
        return
      end
      local parts = {}
      for g = 1, 8 do
        parts[g] = tostring(total ~= nil and total[g] or "")
      end
      local key = table.concat(parts, "|")
      if key == G.boxKey then
        return
      end
      local E = IC.effect
      local list, width = {}, 0
      for g = 1, 8 do
        local v = total ~= nil and total[g] or nil
        local stat = IC.stat_by_index[G.STAT[g] + 1]
        local icon = stat ~= nil and E.stat_icons[stat] or nil
        if v ~= nil and v ~= 0 and icon ~= nil then
          local text = (v > 0 and (IC.plus_colour .. "+") or (IC.minus_colour .. "-")) .. tostring(math.abs(v)) .. "[C]"
          local digits = #tostring(math.abs(v)) + 1
          local w = B.pad + B.icon + B.gap + digits * B.char_px + B.pad
          list[#list + 1] = {icon = icon, text = text, w = w}
          width = width + w + (#list > 1 and B.spacing or 0)
        end
      end
      local rect = IC.rect
      local x = B.align == "right" and rect[3] - B.margin - width or rect[1] + B.margin
      local top = rect[2] - B.h + B.overlap
      local k, done = B.first, true
      for _, b in ipairs(list) do
        if k + 2 < B.first + B.count then
          done = IconSlot(k, x, top, "sprite", {E.atlas, CALC_CRC(E.sprites.chip_off), b.w, B.h}) and done
          done = IconSlot(k + 1, x + B.pad, top + (B.h - B.overlap - B.icon) / 2, "sprite",
            {E.atlas, CALC_CRC(string.format(E.sprites.stat, b.icon)), B.icon, B.icon}) and done
          done = IconSlot(k + 2, x + B.pad + B.icon + B.gap, top + (B.h - B.overlap) / 2, "text",
            {text = b.text, style = "white", scale = B.text_scale}) and done
          k = k + 3
        end
        x = x + b.w + B.spacing
      end
      done = HideUnused(L, k, B.first + B.count - 1) and done
      G.boxKey = done and key or nil
    end

    -- Suerte (no equipment changes it)
    function G.item_card_luck_row()
      local R = IC.row_mark
      if Exists(G.NUM) and Cmd(C.IS_OPEN, G.NUM, R.luck_number) == true then
        for _, m in ipairs(R.luck_arrows) do
          Cmd(C.MESH, G.NUM, m, false, R.luck_number)
        end
      end
      if Exists(G.EXTRA) and Cmd(C.IS_OPEN, G.EXTRA, 0) == true then
        local c = R.label_colour
        pcall(funcLuaMenuCommand, 801406373 --[[material colour of a group]], G.EXTRA, 0, R.label_group, c[1], c[2], c[3])
      end
    end

-- Player page block (plate_pages.lua)
    function G.item_card_text()
      if #G.icPages == 0 or not Exists(IC.layer) or Cmd(C.IS_OPEN, IC.layer, 0) ~= true then
        return
      end
      if IC.text_on_icons then
        Cmd(C.TEXT_VIS, IC.layer, 3138144965 --[[_text_parameter01]], false, 0)
        G.try("item_card_page_icons")
        return
      end
      local body = G.icPages[G.icPage] or G.icBonus
      Cmd(C.SET_TEXT, IC.layer, 3138144965 --[[_text_parameter01]], body, 0)
      -- the text node only on a page that writes in it (the game's bonus lines never show under the Efecto page)
      Cmd(C.TEXT_VIS, IC.layer, 3138144965 --[[_text_parameter01]], body ~= "", 0)
      G.try("item_card_page_icons")
    end

    G.IC_CTRLS = {1332654303 --[[MENU_CTRL]], 2748927068 --[[MENU_CTRL_WITH_ANALOG_MOVE_FOCUS]]}
    local function Pressed(k)
      for _, ctrl in ipairs(G.IC_CTRLS) do
        local ok, hit = pcall(funcLuaCommand, 4265778440, ctrl, k)
        if ok and hit == true then
          return true
        end
      end
      return false
    end

    -- Reads the frame's input while a paged card shows.
    function G.item_card_input()
      -- the item picker's script reads the keys while the picker is up (IC.picker_page_event)
      if G.icPreviewing or not G.item_card_pageable() then
        return
      end
      local dir
      if IC.pager ~= nil and IC.pager.style == "ycycle" then
        dir = Pressed(3421673595 --[[CMD_FUNC3]]) and 1 or 0
      else
        dir = (Pressed(1970176280 --[[CMD_FUNCL2]]) and -1) or (Pressed(2704260807 --[[CMD_FUNCR2]]) and 1) or 0
      end
      if dir ~= 0 then
        G.item_card_turn_page(dir)
      end
    end

    function G.item_card_pageable()
      return G.item_card_paged() and G.item_card_on() and Exists(IC.layer)
        and Cmd(C.IS_OPEN, IC.layer, 0) == true and Cmd(C.IS_VIS, IC.layer, 0) == true
    end

    -- one page back (-1) or forward (1), wrapping
    function G.item_card_turn_page(dir)
      G.icPage = (G.icPage - 1 + dir) % #G.icPages + 1
      pcall(funcLuaCommand, 1917805374, 1228648509)      -- the retail page switch sound (sy0027)
      G.item_card()
      G.item_card_text()
    end

    function G.item_card_pending()
      if G.itemCardPending and G.item_card_on() then
        G.item_card()
        G.item_card_page_icons()
        if not G.itemCardPending and not IC.no_player and G.itemCardLast ~= nil
            and type(SetupEquipInfoWindow) == "function" then
          pcall(SetupEquipInfoWindow, G.itemCardLast)
        end
      end
    end

    if not IC.no_player then
      PlayerPageWrap("GetEquipParamTextOneLine", function(orig)
        return function(item, idx, ...)
          local ok, s = orig(item, idx, ...)
          if ok == true and type(s) == "string" then
            local okS, signed = pcall(G.signed_bonus, s)
            if okS and type(signed) == "string" then
              s = signed
            end
          end
          return ok, s
        end
      end)
      PlayerPageWrap("GetEquipParamText", function(orig)
        return function(item, ...)
          if not G.item_card_on() or type(GetEquipParamTextOneLine) ~= "function" then
            return orig(item, ...)
          end
          local parts = {}
          for k = 0, 7 do
            local ok, s = GetEquipParamTextOneLine(item, k)
            if ok == true and type(s) == "string" and s ~= "" then
              parts[#parts + 1] = s
            end
          end
          G.icBonus = table.concat(parts, IC.bonus_gap)
          return G.icBonus
        end
      end)
      PlayerPageWrap("SetVisibleEquipInfoWindow", function(orig)
        return function(on, ...)
          G.try("item_card_subscribe")
          local r = Pack(orig(on, ...))
          if on ~= true then
            G.item_card_hide()                    -- nothing focused: the rows' own look, no card
          end
          return table.unpack(r, 1, r.n)
        end
      end)
    end

    -- Returns the equip slot 1..4 of an item by its category (nil = not equipment).
    function G.item_card_slot(item)
      local ok, category = pcall(funcLuaCommand, 1883585771 --[[the item's category]], item, 2)
      return ok and IC.set_icons.slot_of_category[tonumber(category) or 0] or nil
    end

    -- Shows the card of `item` after the game filled the card layer (name, icon, chips).
    function G.item_card_show(item, base)
      if item ~= G.icShown then
        G.icPage = 1                          -- another item: its first page
      end
      G.icShown = item
      G.icWornSwap = base ~= nil and {from = base ~= 0 and base or nil, to = item} or nil
      if IC.prio_above_card and Exists(IC.layer) then
        local okP, p = pcall(funcLuaMenuCommand, 1018283794, IC.layer, 0)
        G.icPrioBase = okP and tonumber(p) or G.icPrioBase
      end
      if G.item_card_on() then
        G.try("item_card_pages", item)          -- after the fill: G.icBonus is the item's bonus row
        G.try("item_card")
        G.try("item_card_text")
      end
      if IC.rows ~= false then
        G.try("item_card_rows", item, base)
      end
    end

    -- Hides the card (nothing focused or hovered).
    function G.item_card_hide()
      G.icPages, G.icShown, G.icWornSwap = {}, nil, nil
      if IC.text_on_icons and Exists(IC.layer) and Cmd(C.IS_OPEN, IC.layer, 0) == true then
        Cmd(C.TEXT_VIS, IC.layer, 3138144965 --[[_text_parameter01]], true, 0)   -- another item: the game's own line
      end
      if IC.rows ~= false then
        G.try("item_card_rows", nil)
      end
      G.try("item_card_body", nil, false)
      G.try("item_card_page_icons")
    end

    if not IC.no_player then
      function G.item_card_subscribe()
        if G.icSubscribed or type(VRFW.menu_event) ~= "table" then
          return
        end
        G.icSubscribed = VRFW.menu_event.on(IC.picker_event, IC.menu, IC.picker_owner, function(item)
          item = tonumber(item)
          if item == nil then
            return
          end
          if item < 0 then
            G.icPreviewing = false
            CharacterReforged.player_page_item_card_preview_end()
          else
            G.icPreviewing = true
            CharacterReforged.player_page_item_card_preview(item)
          end
          G.try("bars")
        end)
        VRFW.menu_event.on(IC.picker_page_event, IC.menu, IC.picker_owner, function(dir)
          dir = tonumber(dir)
          if dir ~= nil and G.item_card_pageable() then
            G.item_card_turn_page(dir)
          end
        end)
      end
      PlayerPageWrap("OnInit", function(orig)
        return function(...)
          local r = Pack(orig(...))
          G.try("item_card_subscribe")
          return table.unpack(r, 1, r.n)
        end
      end)

      -- Returns what the hovered item would replace.
      function G.item_card_replaced(item)
        local slot = G.item_card_slot(item)
        if slot == nil then
          return 0
        end
        if type(G.hdl) ~= "number" or type(GetCharaEquipmentIds) ~= "function" then
          return G.itemCardLast or 0
        end
        local okIds, ids = pcall(GetCharaEquipmentIds, G.hdl)
        return okIds and type(ids) == "table" and ids[slot] or 0
      end

      -- Runs after coming back from the picker (an equip or remove there changed the player and the slot).
      PlayerPageWrap("OnChangeLayerGroup", function(orig)
        return function(group, ...)
          local r = Pack(orig(group, ...))
          if group == IC.select_group and type(UpdateEquipItemInfo) == "function" then
            G.icPreviewing = false
            pcall(UpdateEquipItemInfo)
          end
          return table.unpack(r, 1, r.n)
        end
      end)

      function CharacterReforged.player_page_item_card_preview(item)
        if item == nil or item == 0 then
          G.item_card_hide()
          return true
        end
        if type(G.hdl) == "number" then
          local ok, v = pcall(G.values, G.hdl)
          if ok and type(v) == "table" then
            G.vals = v
          end
        end
        G.try("item_card")
        -- Handles the picker's own script having filled the card.
        if type(GetEquipParamText) == "function" then
          pcall(GetEquipParamText, item)
        end
        local replaced = G.item_card_replaced(item)
        G.item_card_show(item, replaced)
        local parts = {}
        for g = 1, 8 do
          local d = G.rowDelta ~= nil and G.rowDelta[g] or nil
          if d ~= nil then
            parts[#parts + 1] = string.format("%s%+d", tostring(G.STAT[g]), d)
          end
        end
        pcall(funcLuaCommand, C.LOG, "picker hover", tostring(item), "vs", tostring(replaced), "delta",
          table.concat(parts, " "), "frames", tostring(G.frameSteps or 0))
        return true
      end
      function CharacterReforged.player_page_item_card_preview_end()
        if G.itemCardLast ~= nil and G.itemCardLast ~= 0 then
          G.try("item_card")
          G.item_card_show(G.itemCardLast, nil)
        else
          G.item_card_hide()
        end
        return true
      end

      PlayerPageWrap("SetupEquipInfoWindow", function(orig)
        return function(item, ...)
          G.try("item_card_subscribe")
          G.itemCardLast = item
          if G.item_card_on() then
            G.try("item_card")                   -- Nodes first: the fill draws the texts / icons where the nodes are.
          end
          local r = Pack(orig(item, ...))
          G.item_card_show(item, nil)
          return table.unpack(r, 1, r.n)
        end
      end)
    else
      -- Watches a screen without a player (inventory, shop).
      function G.item_card_watch()
        if G.icWatched or type(funcLuaMenuCommand) ~= "function" then
          return
        end
        G.icWatched = true
        local raw = funcLuaMenuCommand
        -- Every call goes on with exactly the arguments it got (raw(...)).
        funcLuaMenuCommand = function(...)
          local cmd, layer = ...
          if cmd == C.VIS and IC.layers_set[layer] then
            local r = Pack(raw(...))
            if layer == IC.layer and G.icShown ~= nil then
              G.try("item_card_page_icons")
            end
            return table.unpack(r, 1, r.n)
          end
          return raw(...)
        end
      end
      PlayerPageWrap("SetupItemPositionIcon", function(orig)
        return function(layer, k, item, ...)
          local r = Pack(orig(layer, k, item, ...))
          if IC.layers_set[layer] and type(item) == "number" and item ~= 0 then
            G.try("item_card_watch")
            IC.layer = layer
            G.item_card_layer = layer
            G.item_card_show(item, nil)
          end
          return table.unpack(r, 1, r.n)
        end
      end)
      PlayerPageWrap("ClearItemPositionIcon", function(orig)
        return function(layer, ...)
          local r = Pack(orig(layer, ...))
          if IC.layers_set[layer] and layer == IC.layer and G.icShown ~= nil then
            G.item_card_hide()
          end
          return table.unpack(r, 1, r.n)
        end
      end)
    end
  end

  if G.H.pages then
    PlayerPageWrap("OnChangeFocus", function(orig)
      return function(a1, a2, ...)
        local ok, handled = pcall(G.nav_on_change, a1, a2)
        if ok and handled then
          return
        end
        return orig(a1, a2, ...)
      end
    end)
    for _, name in ipairs({"SetSkillCollisionEnable", "UpdateSkillItemHitCollision"}) do
      PlayerPageWrap(name, function(orig)
        return function(a1, ...)
          local r = Pack(orig(a1, ...))         -- the original first
          if name ~= "SetSkillCollisionEnable" or a1 == true then
            pcall(G.nav_zones)
          end
          return table.unpack(r, 1, r.n)
        end
      end)
    end
  end

  PlayerPageWrap("OnCloseLayer", function(orig)
    return function(a1, ...)
      local r = Pack(orig(a1, ...))
      if a1 == G.PAGE then
        G.ready = {}
        G.rateInit = {}
        G.vals = nil
        CharacterReforged.HYPER_PAGE_MIXIMAX_VIEW = false
        BarsVisible(false)
        G.movesOn = true                    -- next page: the slot nodes back to retail
        pcall(G.fb_hide)
        for _, l in ipairs({G.BAND, G.SLANT, G.TAG, G.FLABEL}) do
          if Cmd(C.IS_OPEN, l, 0) == true then
            Cmd(C.VIS, l, 0, false)
          end
        end
      end

      return table.unpack(r, 1, r.n)
    end
  end)

  if G.H.pages then
    function G.dock_offset(l, i)
      local OFS, DEF = 902337421, 753088835       -- offset01, Default
      local id = Cmd(1352645570, l, OFS, i)
      if Cmd(1914009721, l, id, DEF, 0, i) ~= true then   -- CMND_IS_END_ANIME of the state-0 clip
        Cmd(1380315136, l, i, OFS, 0, DEF)
        Cmd(335638325, l, id, DEF, i)                      -- CMND_STOP_ANIME
      end
      Cmd(3781155141, l, i, OFS, 2, DEF)                   -- CMND_PLAY_ANIME_TYPE offset01 state 2
      pcall(funcLuaCommand, C.LOG, "PlayerPage match offset", tostring(i))
    end
    PlayerPageWrap("SetPersonalPlateType", function(orig)
      return function(a1, ...)
        G.plateType = a1
        return orig(a1, ...)
      end
    end)
    PlayerPageWrap("OnSetupPersonalPlateLayer", function(orig)
      return function(a1, a2, ...)
        local r = Pack(orig(a1, a2, ...))      -- the original first
        if a1 == G.PAGE and G.plateType == 1 and CharacterReforged.PLAYER_PAGE_MATCH_OFFSET ~= false then
          pcall(G.dock_offset, a1, a2 or 0)
        end
        return table.unpack(r, 1, r.n)
      end
    end)
  end
end)()
-- ===== EVT plate_pages plate END =====
